class RemoteConfig(object):
    def __init__(self, config):
        self.config = config

    @staticmethod
    def resolve(name, config=None):
        if not config:
            config = Config()

        remote = config.get(Config.SECTION_REMOTE, name)

        if remote is None:
            return None

        return RemoteBase.resolve(remote)

    def get(self, name, config=None):
