    def add(self, name, url, default=False):
        with self.config.edit() as conf:
            remote = conf.get(Config.SECTION_REMOTE, {})
            if name in remote:
                raise RemoteConfigError(
                    "remote entry with name '{}' already exists".format(name)
                )

            remote.update({name: {Config.SECTION_REMOTE_URL: url}})
            conf[Config.SECTION_REMOTE] = remote

            if default:
                conf[Config.SECTION_CORE] = {Config.SECTION_REMOTE: name}

    def modify(self, name, option, value):
        with self.config.edit() as conf:
            remote = conf.get(Config.SECTION_REMOTE, {})
            if name not in remote:
                raise RemoteConfigError(
                    "remote entry with name '{}' doesn't exist".format(name)
                )

            remote[name].update({option: value})
            conf[Config.SECTION_REMOTE] = remote

    def remove(self, name):
        with self.config.edit() as conf:
            remote = conf.get(Config.SECTION_REMOTE, {})
            if name not in remote:
                raise RemoteConfigError(
                    "remote entry with name '{}' doesn't exist".format(name)
                )

            del remote[name]
            conf[Config.SECTION_REMOTE] = remote

            default = (
                conf.get(Config.SECTION_CORE, {}).get(Config.SECTION_REMOTE)
            )
            if default == name:
                del conf[Config.SECTION_CORE][Config.SECTION_REMOTE]
